'use client';

import Image from "next/image";
import { motion } from "framer-motion";
import { rajdhani, orbitron } from "../../fonts";
import { FaFacebook, FaInstagram, FaDiscord, FaCalendar, FaGamepad, FaClock } from 'react-icons/fa';
import Navbar from '../../components/Navbar';

export default function GameNight() {
  return (
    <div className="flex flex-col min-h-screen relative">
      <video
        className="fixed inset-0 w-full h-full object-cover z-0"
        autoPlay
        loop
        muted
        playsInline
      >
        <source src="/gamelab.mp4" type="video/mp4" />
      </video>
      
      <div className="fixed inset-0 bg-black/75 z-10" />

      <header className="relative overflow-hidden flex flex-col w-full z-20">
        <div className="flex items-center justify-between w-full py-4 px-6 bg-gradient-to-r from-purple-950 to-purple-700">
          <div className="flex items-center gap-3">
            <Image width={80} height={80} alt="GameLab Logo" src="/logo.jpeg" />
            <h1 className={`${rajdhani.className} text-white text-2xl sm:text-3xl font-bold tracking-wider`}>
              GAMELAB
            </h1>
          </div>
          <div className="hidden lg:flex">
            <Navbar />
          </div>
          <div className="flex gap-4">
            <a href="https://www.facebook.com/gamelab.inpt.7" target="_blank" rel="noopener noreferrer" className="text-white hover:text-purple-300 transition-colors duration-300">
              <FaFacebook size={32} />
            </a>
            <a href="https://www.instagram.com/gamelabinpt/" target="_blank" rel="noopener noreferrer" className="text-white hover:text-purple-300 transition-colors duration-300">
              <FaInstagram size={32} />
            </a>
            <a href="https://discord.gg/kqSCjXQJ" target="_blank" rel="noopener noreferrer" className="text-white hover:text-purple-300 transition-colors duration-300">
              <FaDiscord size={32} />
            </a>
          </div>
        </div>
      </header>

      <main className="flex-1 px-6 py-16 relative z-20">
        <div className="max-w-5xl mx-auto">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            className="bg-gradient-to-br from-green-900/50 to-black/60 backdrop-blur-md rounded-2xl p-10 border border-green-500/40"
          >
            <div className="text-center mb-8">
              <h1 className={`${orbitron.className} text-5xl sm:text-7xl font-bold text-white mb-4`}>
                🎮 GameNight
              </h1>
              <div className="flex items-center justify-center gap-3 text-green-400 text-xl">
                <FaCalendar />
                <span>Tous les Vendredis</span>
              </div>
            </div>

            <div className="mb-8">
              <h2 className={`${rajdhani.className} text-3xl font-bold text-white mb-4`}>
                À Propos de l'Événement
              </h2>
              <p className="text-gray-300 text-lg leading-relaxed mb-4">
                Chaque vendredi soir, le GameLab ouvre ses portes pour une soirée gaming décontractée! 
                Que vous soyez compétitif ou juste là pour le fun, GameNight est l'occasion parfaite de 
                décompresser après une semaine d'études.
              </p>
              <p className="text-gray-300 text-lg leading-relaxed">
                Ambiance chill, gaming entre amis, et découverte de nouveaux jeux. Tous les niveaux sont 
                les bienvenus - l'important c'est de s'amuser!
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
              <div className="bg-black/40 rounded-xl p-6 border border-green-500/30">
                <FaClock className="text-green-500 text-4xl mb-3" />
                <h3 className={`${rajdhani.className} text-white text-xl font-bold mb-2`}>
                  Horaires
                </h3>
                <p className="text-green-400 text-lg">19h00 - 23h00</p>
                <p className="text-gray-400 text-sm mt-2">Tous les vendredis soirs</p>
              </div>

              <div className="bg-black/40 rounded-xl p-6 border border-green-500/30">
                <FaGamepad className="text-green-500 text-4xl mb-3" />
                <h3 className={`${rajdhani.className} text-white text-xl font-bold mb-2`}>
                  Au Programme
                </h3>
                <p className="text-green-400 text-lg">Gaming libre</p>
                <p className="text-gray-400 text-sm mt-2">Tous les jeux sont permis!</p>
              </div>
            </div>

            <div className="mb-8">
              <h2 className={`${rajdhani.className} text-3xl font-bold text-white mb-4`}>
                Ce que nous offrons
              </h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {[
                  'Stations de jeu PC et consoles',
                  'Wi-Fi haute vitesse',
                  'Espace confortable et climatisé',
                  'Snacks et boissons disponibles',
                  'Tournois improvisés',
                  'Découverte de nouveaux jeux'
                ].map((item, index) => (
                  <div key={index} className="flex items-center gap-3 bg-black/30 p-4 rounded-lg">
                    <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                    <span className="text-gray-300">{item}</span>
                  </div>
                ))}
              </div>
            </div>

            <div className="bg-yellow-500/10 border border-yellow-500/30 rounded-xl p-6 mb-8">
              <h3 className={`${rajdhani.className} text-yellow-400 text-xl font-bold mb-2`}>
                ⚠️ Places Limitées
              </h3>
              <p className="text-gray-300">
                Les places sont limitées! Inscrivez-vous à l'avance pour garantir votre spot. 
                Les membres du club ont la priorité.
              </p>
            </div>

            <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <a href="/inscription">
                <motion.button
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  className="px-10 py-4 bg-gradient-to-r from-green-600 to-teal-600 hover:from-green-700 hover:to-teal-700 text-white font-bold rounded-lg transition-all duration-300 uppercase tracking-wider text-lg"
                >
                  Réserver ma place
                </motion.button>
              </a>
              <a href="/devenir-membre">
                <motion.button
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  className="px-10 py-4 border-2 border-white bg-transparent hover:bg-white hover:text-black text-white font-bold rounded-lg transition-all duration-300 uppercase tracking-wider text-lg"
                >
                  Devenir membre
                </motion.button>
              </a>
            </div>
          </motion.div>
        </div>
      </main>
    </div>
  );
}
